import{_ as t,o,c as a,a0 as r}from"./chunks/framework.C0WKPwzJ.js";const u=JSON.parse('{"title":"Hosted apps","description":"How people sign in to the ticket UI, operator console, and business console.","frontmatter":{"title":"Hosted apps","description":"How people sign in to the ticket UI, operator console, and business console."},"headers":[],"relativePath":"hosted.md","filePath":"hosted.md","lastUpdated":1788171427000}'),s={name:"hosted.md"};function n(i,e,d,p,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="hosted-apps" tabindex="-1">Hosted apps <a class="header-anchor" href="#hosted-apps" aria-label="Permalink to &quot;Hosted apps&quot;">​</a></h1><p>Copyright (c) 2026 Devrecated.</p><p>Autodevelop hosted apps do not offer public registration. The Cursor plugin token under <strong>Plugins → Configure</strong> is not a website login.</p><table tabindex="0"><thead><tr><th>App</th><th>Who signs in</th><th>How they get an account</th></tr></thead><tbody><tr><td>Ticket UI</td><td>Organization members</td><td>An operator invites the member. The member signs in and files a typed request. They can review tickets they filed. The same UI opens from a button in your product (<a href="./integration">Integration</a>).</td></tr><tr><td>Operator console</td><td>Operators</td><td>Create the user in the dashboard, then they sign in. Operators connect GitHub, invite members, and review the organization.</td></tr><tr><td>Business console</td><td>Owners and executives</td><td>An operator assigns access, then they sign in. Owners review work, team activity, delivery value, usage, payment, and weekly meetings.</td></tr><tr><td>CLI login</td><td>People who run the Autodevelop CLI</td><td>The same email and password. The CLI opens this page with a device code.</td></tr></tbody></table><p>An operator issues each subscription. The secret is shown once. Never commit it.</p><p>When an organization is lapsed or canceled, paid tools return <strong><code>Your billing has expired</code></strong>. GitHub issues and instance <code>config.json</code> stay in the consumer repository.</p><p>Root license is <a href="https://github.com/devprecated/autodevelop-docs/blob/master/LICENSE.md" target="_blank" rel="noreferrer">PolyForm Noncommercial</a>. Commercial use needs a license from Devrecated.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./guide">Client guide</a></li><li><a href="./cli">CLI</a></li><li><a href="./github">GitHub App</a></li><li><a href="./integration">Integration</a></li></ul>',9)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
